parameters.jsCode:
// Prepare Patient Discharge Context for Clinical Assistant
const body = $json.body || $json;
const patientId = body.patientId || 'P1001';
const question = body.question || 'Can I take my medication with food?';

const patientRecords = {
  P1001: {
    name: 'Alex Kumar',
    diagnosis: 'Type 2 Diabetes Mellitus, Mild Hypertension',
    medications: 'Metformin 500mg (twice daily after meals), Amlodipine 5mg (once daily morning)',
    diet: 'Low sugar, high fiber, reduced carbohydrates',
    restrictions: 'Avoid heavy lifting for 1 week'
  },
  P1002: {
    name: 'Priya Sharma',
    diagnosis: 'Acute Bronchitis',
    medications: 'Azithromycin 500mg (once daily for 3 days), Cetirizine 10mg (once at night for 5 days)',
    diet: 'Warm fluids, avoid cold drinks',
    restrictions: 'Rest for 3-4 days'
  },
  P1003: {
    name: 'Arun Raj',
    diagnosis: 'Post-operative recovery - Appendectomy',
    medications: 'Paracetamol 650mg (every 6 hours if needed for pain), Pantoprazole 40mg (once daily before breakfast)',
    diet: 'Light, easily digestible food',
    restrictions: 'No heavy lifting for 4 weeks'
  }
};

const context = patientRecords[patientId] || patientRecords['P1001'];

return [{
  json: {
    patientId,
    question,
    patientContext: context
  }
}];

