parameters.jsCode:
// Format response for MedGuideAI frontend chat
const response = $json;
let answerText = '';

try {
  answerText = response.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';
} catch (e) {
  answerText = 'Please take your medications as directed in your discharge summary. If you experience severe symptoms, contact your doctor immediately.';
}

if (!answerText) {
  answerText = 'Please consult your care team or follow the instructions in your discharge summary.';
}

return [{
  json: {
    from: 'ai',
    text: answerText,
    time: new Date().toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' }),
    status: 'Delivered'
  }
}];
